mapper.select:
SELECT v.* FROM `video` v
INNER JOIN `video_like` vl ON v.id = vl.video_id
WHERE vl.user_id = #{userId}
ORDER BY vl.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT v.* FROM `video` v
INNER JOIN `video_like` vl ON v.id = vl.video_id
WHERE vl.user_id = #{userId}

    AND (v.title LIKE CONCAT('%',#{keyword},'%') OR v.hashtag LIKE CONCAT('%',#{keyword},'%'))


    AND v.type = #{type}


    AND v.category = #{category}

ORDER BY vl.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM `video_like` vl
INNER JOIN `video` v ON v.id = vl.video_id
WHERE vl.user_id = #{userId}

    AND (v.title LIKE CONCAT('%',#{keyword},'%') OR v.hashtag LIKE CONCAT('%',#{keyword},'%'))


    AND v.type = #{type}


    AND v.category = #{category}
